INSERT INTO TB_ACCT_MST
     ( ACCT_NO
     , CUST_ID
     , PROD_CD
     , OPEN_BR
     , OPEN_AMT
     , ACCT_STAT
     , OPEN_DT
     , REG_ID
     , REG_DTM )
VALUES
     ( #{acctNo}
     , #{custId}
     , #{prodCd}
     , #{openBr}
     , #{openAmt}
     , #{acctStat}
     , TO_CHAR(SYSDATE, 'YYYYMMDD')
     , #{regId}
     , SYSDATE )
